[data-thread-terminal-drawer]{background:linear-gradient(rgba(4,8,14,.55),rgba(4,8,14,.55)),var(--dw-bg) !important;border-top-color:rgba(160,195,230,.1) !important}
[data-thread-terminal-drawer] [class*="terminal-background"]{background:transparent !important}
[data-thread-terminal-drawer] .flex[class*="terminal-background"]{padding:10px 8px 8px 14px}
[data-thread-terminal-drawer] canvas{mix-blend-mode:screen}
@media (prefers-reduced-motion:reduce){[data-workspace-area="conversation"]{background:var(--dw-bg) !important}}
.messages-timeline-scroll{background:transparent !important}
[data-chat-header]{background:rgba(8,14,22,.45) !important;border-bottom-color:rgba(160,195,230,.07) !important;backdrop-filter:blur(14px) saturate(1.2);-webkit-backdrop-filter:blur(14px) saturate(1.2)}
[data-slot="sidebar"]{background:transparent !important;padding:8px 0 8px 8px !important;border:0 !important}
[data-slot="sidebar-inner"]{background:rgba(255,255,255,.035) !important;border:1px solid rgba(160,195,230,.09) !important;border-radius:14px !important;overflow:hidden;backdrop-filter:blur(18px) saturate(1.2);-webkit-backdrop-filter:blur(18px) saturate(1.2)}
[data-thread-item] [aria-current]:not([aria-current="false"]){background:linear-gradient(90deg,rgba(127,182,227,.20),rgba(127,182,227,.08)) !important;box-shadow:inset 0 0 0 1px rgba(127,182,227,.28),0 0 18px rgba(127,182,227,.12) !important;border-radius:8px}
[data-user-message-bubble]{background:rgba(110,160,210,.18) !important;border-color:transparent !important;backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}
.chat-markdown-codeblock{background:rgba(0,0,0,.35) !important;border-color:rgba(160,195,230,.08) !important}
[data-slot="composer-host"]{background:rgba(14,26,42,.65) !important;border:1px solid rgba(127,182,227,.22) !important;backdrop-filter:blur(18px) saturate(1.2);-webkit-backdrop-filter:blur(18px) saturate(1.2)}
[data-thread-details-card]{background:rgba(10,18,28,.6) !important;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}
::selection{background:rgba(127,182,227,.35);color:#fff}
::-webkit-scrollbar{width:8px;height:8px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:rgba(127,182,227,.22);border-radius:8px}
::-webkit-scrollbar-thumb:hover{background:rgba(127,182,227,.42)}
[data-slot="scroll-area-thumb"]{background:rgba(127,182,227,.28) !important}
[data-slot="scroll-area-scrollbar"]:hover [data-slot="scroll-area-thumb"]{background:rgba(127,182,227,.45) !important}
